const { exec } = require("child_process");

function makeThumbnail(file, cb) {
  // Resize an uploaded image using ImageMagick.
  const out = file + ".thumb.png";
  const cmd = "convert " + file + " -resize 200x200 " + out;
  exec(cmd, cb);
}

module.exports = makeThumbnail;

